# `POST /v1/compare`: two saved Results of the same query family.
CompareRequest = TypedDict(
    "CompareRequest",
    {
        # A Result of the same family as `before`.
        "after": RouteResult | MatrixResult | ReachResult | dict[str, Any],
        # A saved `vigo.route.v1`, `vigo.matrix.v1` or `vigo.reach.v1` Result.
        # Internal trace results are also accepted, without stability guarantees.
        "before": RouteResult | MatrixResult | ReachResult | dict[str, Any],
        # `trace` adds the internal comparison.
        "diagnostics": NotRequired[DiagnosticsLevel],
        "id": NotRequired[Any],
    },
)

# Any document the engine writes for a query, keyed by its `schema`.
Response = RouteResult | MatrixResult | ReachResult | CompareResult | InfoResult | CollectionInfoResult | StreamDetail | ErrorResult
